var ENT=[["Trifacta", "Visual wrangling suggesting transforms."], ["Talend", "Open-source data integration studio."], ["Pentaho Kettle", "ETL with a visual designer."], ["Apache NiFi", "Flow-based data routing and transform."], ["pandas", "Python's DataFrame library; the workhorse of tabular cleaning and reshaping."], ["OpenRefine", "A free tool for messy-data wrangling: clustering, faceting, reconciliation."], ["dbt", "SQL-based transformation with testing and docs; the analytics-engineering standard."]];
